-
-  private NinjaToken push(NinjaToken token) {
-    step.ensureEnd();
-    ranges.add(Pair.of(step.getStart(), step.getEnd()));
-    tokens.add(token);
-    if (step.getError() != null) {
-      // Do not move in case of error.
