-      list.sort(Comparator.comparing(Pair::getFirst));
-    }
-    for (List<Pair<Long, NinjaRule>> list : rules.values()) {
-      list.sort(Comparator.comparing(Pair::getFirst));
-    }
-    for (List<Pair<Long, NinjaPool>> list : pools.values()) {
-      list.sort(Comparator.comparing(Pair::getFirst));
-    }
-  }
