+        StarlarkSemantics semantics,
+        Depset valuesSet,
+        StarlarkCallable mapEach,
+        String joinWith) {
+      super(key);
+      this.semantics = semantics;
+      this.valuesSet = valuesSet;
+      this.mapEach = mapEach;
+      this.joinWith = joinWith;
+    }
