+    String host = Preconditions.checkNotNull(uri.getHost());
+    Optional<Path> credentialHelper =
+        findHostCredentialHelper(host)
+            .or(() -> findWildcardCredentialHelper(host))
+            .or(() -> defaultHelper);
+    return credentialHelper.map(CredentialHelper::new);
+  }
