+  @VisibleForTesting
+  static Optional<String> parentDomain(String domain) {
+    int dot = domain.indexOf('.');
+    if (dot < 0) {
+      // We reached the last segment, end.
+      return Optional.empty();
+    }
+
+    return Optional.of(domain.substring(dot + 1));
+  }
